class LCMaaSVersionNotSupported(Exception):
    """ Raises when provided LCMaaS version is not supported. """


class IncorrectLoginCredentials(Exception):
    """ Raises when credentials are wrong. """
    def __init__(self, error_message):
        super(IncorrectLoginCredentials, self).__init__()
        self.error_message = error_message

    def __str__(self):
        return 'Invalid username or password - {}'.format(self.error_message)


class HostConnectedFailed(Exception):
    """ Raises when LCMaaS host can not be connected. """
    def __init__(self, error_message):
        super(HostConnectedFailed, self).__init__()
        self.error_message = error_message

    def __str__(self):
        return 'LCMaaS host can not be reached - {}'.format(self.error_message)
